#!/usr/bin/env python3
from pathlib import Path
import numpy as np,json,hashlib
P=Path(__file__).resolve().parent;plan=json.loads((P/'asset_contract.json').read_text());ATOM=np.dtype([('x','<f4'),('y','<f4'),('z','<f4'),('type','<i4')]);FF=np.dtype([('hb','<i4'),('radius','<f4'),('hphb','<f4'),('elsc','<f4')]);rows=[]
for c in plan['cases']:
 k=c['index'];n=c['n'];p=np.fromfile(P/f'case{k}_protein.bin',dtype=ATOM);l=np.fromfile(P/f'case{k}_ligand.bin',dtype=ATOM);f=np.fromfile(P/f'case{k}_forcefield.bin',dtype=FF);t=np.fromfile(P/f'case{k}_poses.bin',dtype='<f4').reshape(6,n).astype('f8');out=np.fromfile(P/f'case{k}_oracle_channels_f64.bin',dtype='<f8').reshape(n,6);xyz=np.memmap(P/f'case{k}_oracle_transformed_xyz_f64.bin',mode='r',dtype='<f8').reshape(n,len(l),3);idx=np.linspace(0,n-1,33,dtype=int)if k==0 else np.arange(n);maxerr=0.;maxxyz=0.
 lp=np.array([l['x'],l['y'],l['z']],dtype='f8').T;pp=np.array([p['x'],p['y'],p['z']],dtype='f8').T;lf=f[l['type']];pf=f[p['type']];radius=lf['radius'].astype('f8')[:,None]+pf['radius'].astype('f8')[None,:];h1=lf['hphb'].astype('f8')[:,None];h2=pf['hphb'].astype('f8')[None,:];cutoff=np.where((lf['hb'][:,None]==70)&(pf['hb'][None,:]==70),4.,2.);charge0=lf['elsc'].astype('f8')[:,None]*pf['elsc'].astype('f8')[None,:];special=(lf['hb'][:,None]==69)|(pf['hb'][None,:]==69);length=np.where((h1<0)&(h2<0),5.5,1.);amp=np.where((h2<0)&(h1>0),-h2,h2)+np.where((h2>0)&(h1<0),-h1,h1);active=(h2!=0)&((h1<0)|(h2<0))
 for begin in range(0,len(idx),8):
  ix=idx[begin:begin+8];m=len(ix);rx=np.tile(np.eye(3),(m,1,1));ry=rx.copy();rz=rx.copy();sx,cx=np.sin(t[0,ix]),np.cos(t[0,ix]);sy,cy=np.sin(t[1,ix]),np.cos(t[1,ix]);sz,cz=np.sin(t[2,ix]),np.cos(t[2,ix]);rx[:,1,1]=cx;rx[:,1,2]=-sx;rx[:,2,1]=sx;rx[:,2,2]=cx;ry[:,0,0]=cy;ry[:,0,2]=sy;ry[:,2,0]=-sy;ry[:,2,2]=cy;rz[:,0,0]=cz;rz[:,0,1]=-sz;rz[:,1,0]=sz;rz[:,1,1]=cz;R=rz@ry@rx;pos=np.einsum('nij,lj->nli',R,lp)+t[3:,ix].T[:,None,:];d=np.linalg.norm(pos[:,:,None,:]-pp[None,None,:,:],axis=-1);surface=d-radius;steric=76*np.maximum(0,1-d/radius);charge=45*charge0*np.clip(1-np.maximum(surface,0)/cutoff,0,1);charge=np.where(special,-abs(charge),charge);hydro=amp*np.clip(1-np.maximum(surface,0)/length,0,1)*active;calc=np.stack([.5*(steric+charge+hydro).sum((1,2)),.5*steric.sum((1,2)),.5*charge.sum((1,2)),.5*hydro.sum((1,2)),.5*(abs(steric)+abs(charge)+abs(hydro)).sum((1,2))],axis=1);err=float(abs(calc-out[ix,:5]).max());xe=float(abs(pos-xyz[ix]).max());maxerr=max(maxerr,err);maxxyz=max(maxxyz,xe);assert np.allclose(calc,out[ix,:5],atol=1e-8,rtol=1e-12);assert xe<1e-12
 rows.append({'case':k,'poses_independently_tensor_checked':len(idx),'maximum_F64_channel_difference':maxerr,'maximum_transformed_coordinate_difference':maxxyz,'oracle_file_sha256':hashlib.sha256((P/f'case{k}_oracle_channels_f64.bin').read_bytes()).hexdigest(),'transformed_file_sha256':hashlib.sha256((P/f'case{k}_oracle_transformed_xyz_f64.bin').read_bytes()).hexdigest(),'energy_range':[float(out[:,0].min()),float(out[:,0].max())]})
a=np.fromfile(P/'case3_oracle_channels_f64.bin',dtype='<f8').reshape(31,6);known={0:13.,2:-6.,5:-25.,24:0.,25:0.,26:0.}
for i,e in known.items():assert abs(a[i,0]-e)<1e-12
u=np.fromfile(P/'case4_oracle_channels_f64.bin',dtype='<f8').reshape(257,6);v=np.fromfile(P/'case5_oracle_channels_f64.bin',dtype='<f8').reshape(257,6);translation_error=float(abs(u[:,:5]-v[:,:5]).max());assert translation_error<1e-10
receipt={'all_pass':True,'CPU_tensor_checks_independent_of_compiled_oracle_and_source_GPU':True,'whole_full_BM1_CPP_oracle_pairs':1598291968,'numpy_tensor_scope':'33stratifiedfullBM1poses andallposesinother5cases; total836, notfull65536NumPy certificate','numpy_tensor_checked_poses':sum(r['poses_independently_tensor_checked']for r in rows),'analytic_known_pair_energies':known,'rigid_joint_translation_maximum_F64_channel_error':translation_error,'rows':rows,'numpy_version':np.__version__};(P/'independent_oracle_audit.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt))
